import os

from langchain.agents import create_agent
from langchain_core.tools import tool

@tool
def search_delivery_policy(topic: str) -> str:
    """Search the synthetic public delivery policy."""

    policies = {
        "delay": (
            "Delivery delays exceeding 48 hours "
            "qualify for support review."
        )
    }

    return policies.get(
        topic.lower(),
        "No matching policy found."
    )

agent = create_agent(
    model=os.environ["AGENT_MODEL"],
    tools=[search_delivery_policy],
    system_prompt=(
        "You are a delivery support assistant. "
        "Use verified policy evidence."
    )
)

result = agent.invoke(
    {
        "messages": [
            {
                "role": "user",
                "content": (
                    "What happens when delivery "
                    "is delayed?"
                )
            }
        ]
    },
    config={"recursion_limit": 12}
)

print(result["messages"][-1].content)

from typing import TypedDict

from langgraph.graph import (
    StateGraph,
    START,
    END
)

class SupportState(TypedDict):
    order_id: str
    delayed_hours: int
    eligible: bool
    response: str

def investigate(state):

    # Synthetic API response
    return {"delayed_hours": 72}

def evaluate_policy(state):

    return {
        "eligible": state["delayed_hours"] > 48
    }

def route(state):

    if state["eligible"]:
        return "prepare_review"

    return "respond"

def prepare_review(state):

    return {
        "response": (
            "Order qualifies for support review. "
            "No compensation has been issued."
        )
    }

def respond(state):

    return {
        "response": (
            "Order does not qualify under "
            "the current delay policy."
        )
    }

builder = StateGraph(SupportState)

builder.add_node("investigate", investigate)
builder.add_node("evaluate", evaluate_policy)
builder.add_node("prepare_review", prepare_review)
builder.add_node("respond", respond)

builder.add_edge(START, "investigate")
builder.add_edge("investigate", "evaluate")

builder.add_conditional_edges(
    "evaluate",
    route,
    {
        "prepare_review": "prepare_review",
        "respond": "respond"
    }
)

builder.add_edge("prepare_review", END)
builder.add_edge("respond", END)

graph = builder.compile()

result = graph.invoke({
    "order_id": "ORD-101",
    "delayed_hours": 0,
    "eligible": False,
    "response": ""
})

print(result["response"])

