from opentelemetry import trace
from opentelemetry.trace import Status, StatusCode

tracer = trace.get_tracer(
    "enterprise.agents"
)

def traced_tool_call(
    tool_name,
    execute
):

    with tracer.start_as_current_span(
        "agent.tool.execute"
    ) as span:

        span.set_attribute(
            "agent.tool.name",
            tool_name
        )

        try:

            result = execute()

            span.set_attribute(
                "agent.tool.outcome",
                "returned"
            )

            return result

        except Exception as exc:

            span.set_attribute(
                "error.type",
                type(exc).__name__
            )

            span.set_status(
                Status(StatusCode.ERROR)
            )

            raise

